solution:
function rateLimit(requests, limit, windowMs) {
  const queues = new Map();
  const out = [];
  for (const [client, tsRaw] of requests) {
    const ts = Number(tsRaw);
    let q = queues.get(client);
    if (!q) { q = []; queues.set(client, q); }
    while (q.length && q[0] <= ts - windowMs) q.shift();
    if (q.length < limit) { q.push(ts); out.push(true); } else out.push(false);
  }
  return out;
}
